CREATE TABLE IF NOT EXISTS book_purchase_counts(book_id TEXT PRIMARY KEY,count INTEGER NOT NULL DEFAULT 0 CHECK(count>=0));
INSERT OR IGNORE INTO book_purchase_counts(book_id,count) SELECT json_extract(j.value,'$.id'),COUNT(*) FROM orders o,json_each(o.items) j WHERE o.status='paid' AND o.mode='live' GROUP BY json_extract(j.value,'$.id');
CREATE TRIGGER IF NOT EXISTS count_live_purchase AFTER UPDATE OF status ON orders WHEN NEW.status='paid' AND OLD.status!='paid' AND NEW.mode='live' BEGIN INSERT INTO book_purchase_counts(book_id,count) SELECT json_extract(value,'$.id'),COUNT(*) FROM json_each(NEW.items) WHERE json_extract(value,'$.id') IS NOT NULL GROUP BY json_extract(value,'$.id') ON CONFLICT(book_id) DO UPDATE SET count=book_purchase_counts.count+excluded.count; END;
CREATE TRIGGER IF NOT EXISTS count_inserted_live_purchase AFTER INSERT ON orders WHEN NEW.status='paid' AND NEW.mode='live' BEGIN INSERT INTO book_purchase_counts(book_id,count) SELECT json_extract(value,'$.id'),COUNT(*) FROM json_each(NEW.items) WHERE json_extract(value,'$.id') IS NOT NULL GROUP BY json_extract(value,'$.id') ON CONFLICT(book_id) DO UPDATE SET count=book_purchase_counts.count+excluded.count; END;
